{
 "summary": "Intermittent checkout 502s originate in inventory, which began logging 'deadlock detected' and returning 500 on POST /reserve 3 seconds after inventory was deployed 3.1.5 -> 3.2.3 at 07:51:23Z. Orders and gateway only propagate the failure (502s). Error ratio peaked near 14% at gateway and 19.6% at inventory/orders, with no latency regression; the inventory 3.2.3 deploy is the prime suspect and rollback is the fastest mitigation.",
 "root_cause": {
  "statement": "Inventory release 3.2.3 (deployed 07:51:23Z) introduced a database deadlock in the POST /reserve path, causing intermittent 500s that orders and gateway surface as 502 checkout failures. The link to the deploy is temporal (deadlock errors start 3s after deploy, only on release 3.2.3) rather than proven by a code diff.",
  "service": "inventory",
  "confidence": "medium",
  "evidence_ids": [
   "ev-5a775fafa68e",
   "ev-83d3f7f5d610",
   "ev-602949a82a04",
   "ev-82692c2145f8"
  ]
 },
 "contributing_factors": [
  {
   "statement": "Orders does not handle inventory 500s gracefully; it converts them into 502s, which gateway propagates to the client as a failed checkout.",
   "evidence_ids": [
    "ev-2305e65a1cdd",
    "ev-b206dbbc65ab",
    "ev-602949a82a04"
   ]
  }
 ],
 "timeline": [
  {
