   ]
  },
  {
   "time": "2026-10-23T07:51:26Z",
   "event": "inventory begins logging 'deadlock detected'; orders logs reservation failures (500) and gateway logs 'checkout failed: orders returned 502', all on the same traces",
   "evidence_ids": [
    "ev-83d3f7f5d610",
    "ev-2305e65a1cdd",
    "ev-b206dbbc65ab"
   ]
  },
  {
   "time": "2026-10-23T07:52:00Z",
   "event": "First sampled failing trace: gateway 502 <- orders 502 <- inventory POST /reserve 500",
   "evidence_ids": [
    "ev-602949a82a04"
   ]
  },
  {
   "time": "2026-10-23T07:52:08Z",
   "event": "5xx ratio crosses 5% on gateway, orders and inventory",
   "evidence_ids": [
    "ev-2108a3e30653",
    "ev-b97d4a38bc90",
    "ev-82692c2145f8"
   ]
  },
  {
   "time": "2026-10-23T07:53:52Z",
