   "evidence_ids": [
    "ev-83d3f7f5d610",
    "ev-b206dbbc65ab",
    "ev-2108a3e30653"
   ]
  }
 ],
 "ruled_out": [
  {
   "statement": "Orders or gateway as origin: their errors are explicitly reactions to downstream failures (orders cites inventory 500, gateway cites orders 502), and the trace error path terminates at inventory.",
   "evidence_ids": [
    "ev-2305e65a1cdd",
    "ev-b206dbbc65ab",
    "ev-602949a82a04"
   ]
  },
  {
   "statement": "Timeout/latency cascade: no p95 latency onset on any service, failing traces complete in 9-31ms, and inventory p95 stays around 44-47ms.",
   "evidence_ids": [
    "ev-602949a82a04",
    "ev-82692c2145f8",
    "ev-b97d4a38bc90",
    "ev-2108a3e30653"
   ]
  },
  {
   "statement": "Deploys of gateway or orders: the only deployment record in the window is inventory; gateway 1.4.2 and orders 2.7.0 have no recorded change.",
   "evidence_ids": [
    "ev-5a775fafa68e"
   ]
  }
 ],
 "unknowns": [
  "No database metrics or logs (lock waits, deadlock graphs) to confirm the deadlock is in inventory's datastore and what query/transaction pair is involved.",
  "No pre-deploy baseline for inventory error ratio or deadlock logs on 3.1.5 to confirm the errors are new with 3.2.3.",
  "Content of the 3.1.5 -> 3.2.3 change (e.g. transaction ordering, schema migration) is not in the evidence.",
  "Whether the error rate is still rising or stable beyond the window end."
 ],
 "recommended_actions": [
  {
   "action": "Roll back inventory to 3.1.5.",
   "rationale": "Deadlock errors began 3s after the 3.2.3 deploy and occur only on that release; rollback is the fastest way to confirm and mitigate.",
   "evidence_ids": [
    "ev-5a775fafa68e",
    "ev-83d3f7f5d610"
   ]
  },
  {
   "action": "Inspect inventory's database deadlock logs and the 3.2.3 diff for changes to transaction/lock ordering in the reserve path.",
   "rationale": "Inventory POST /reserve is the failing span and logs 'deadlock detected'.",
   "evidence_ids": [
    "ev-602949a82a04",
    "ev-83d3f7f5d610"
   ]
  },
  {
   "action": "After rollback, verify gateway/orders/inventory 5xx ratio returns below 5% and deadlock logs stop.",
   "rationale": "Confirms causation and resolution using the same metrics that showed the onset.",
   "evidence_ids": [
    "ev-2108a3e30653",
    "ev-b97d4a38bc90",
    "ev-82692c2145f8"
   ]
  },
  {
   "action": "Consider retry-on-deadlock in inventory reserve transactions and clearer error mapping in orders.",
   "rationale": "Transient deadlocks currently surface directly as user-facing checkout failures.",
   "evidence_ids": [
    "ev-2305e65a1cdd",
    "ev-b206dbbc65ab"
   ]
  }
 ]
